begin
  select id into v_en_id from public.languages where code = 'en' limit 1;
  if v_en_id is null then raise exception 'English language row not found'; end if;
  select p.id into v_product_reading from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-reading' order by p.created_at asc limit 1;
  if v_product_reading is null then raise exception 'english-reading product not found'; end if;
  select p.id into v_product_listening from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-listening' order by p.created_at asc limit 1;
  if v_product_listening is null then raise exception 'english-listening product not found'; end if;
  select p.id into v_product_writing from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-writing' order by p.created_at asc limit 1;
  if v_product_writing is null then raise exception 'english-writing product not found'; end if;
  select p.id into v_product_speaking from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-speaking' order by p.created_at asc limit 1;
  if v_product_speaking is null then raise exception 'english-speaking product not found'; end if;
  select p.id into v_product_grammar from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-grammar' order by p.created_at asc limit 1;
  if v_product_grammar is null then raise exception 'english-grammar product not found'; end if;
  select p.id into v_product_immersion from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-immersion' order by p.created_at asc limit 1;
  if v_product_immersion is null then raise exception 'english-immersion product not found'; end if;
  select p.id into v_product_vocabulary from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-vocabulary' order by p.created_at asc limit 1;
  if v_product_vocabulary is null then raise exception 'english-vocabulary product not found'; end if;

  -- reading: a1-a-rainy-day-in-tashkent (A1)
  if exists (select 1 from public.reading_articles where product_id = v_product_reading and language_id = v_en_id and slug = 'a1-a-rainy-day-in-tashkent') then
    raise notice 'skipped existing reading item %', 'a1-a-rainy-day-in-tashkent';
  else
    insert into public.reading_articles (slug, title, level, status, sort_order, metadata, summary, content_markdown, category, theme, tone, read_time_minutes, is_hot, questions, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.summary, r.content_markdown, r.category, r.theme, r.tone, r.read_time_minutes, r.is_hot, r.questions, v_product_reading, v_en_id
    from jsonb_populate_record(null::public.reading_articles, $seed${"slug":"a1-a-rainy-day-in-tashkent","title":"A Rainy Day in Tashkent","level":"A1","status":"published","sort_order":200,"metadata":{"genre":"story","writing_tone":"light","word_count":119},"summary":"Jasur has no umbrella on a rainy morning, but a kind woman at the bus stop helps him.","content_markdown":"It is Tuesday morning in Tashkent. Jasur looks out of the window. The sky is grey, and it is very cold. \"It's fine,\" he thinks. \"It never rains in October.\"\n\nHe takes his bag and goes to the bus stop. He doesn't have an umbrella. Then the rain starts. It rains and rains! Jasur's jacket is wet, and his shoes are wet too.\n\nAt the bus stop, there is a woman with a big red umbrella. She smiles at Jasur. \"Come here,\" she says. \"My umbrella is very big.\" They stand under the umbrella together and talk about the weather.\n\nThe bus comes, and Jasur says, \"Thank you very much!\" Now he always has an umbrella in his bag.","category":"Everyday","theme":"weather","tone":"mint","read_time_minutes":1,"is_hot":false,"questions":[{"id":"q1","type":"mcq","prompt":"What is the story about?","options":["Jasur buys a new jacket.","Jasur is late for school.","A woman helps Jasur on a rainy day.","Jasur loses his bag on the bus."],"answer_index":2,"explanation":"It rains, Jasur has no umbrella, and a woman says \"Come here… My umbrella is very big.\"","skill":"reading.main_idea"},{"id":"q2","type":"mcq","prompt":"What is the weather like in the morning?","options":["Grey and cold","Sunny and warm","Hot and dry","Snowy"],"answer_index":0,"explanation":"\"The sky is grey, and it is very cold.\"","skill":"reading.detail"},{"id":"q3","type":"mcq","prompt":"What colour is the woman's umbrella?","options":["Grey","Blue","Black","Red"],"answer_index":3,"explanation":"\"There is a woman with a big red umbrella.\"","skill":"reading.detail"},{"id":"q4","type":"mcq","prompt":"Why does Jasur go out without an umbrella?","options":["He doesn't have one at home.","He thinks it will not rain.","He likes the rain.","His umbrella is broken."],"answer_index":1,"explanation":"He thinks: \"It never rains in October.\"","skill":"reading.inference"},{"id":"q5","type":"mcq","prompt":"\"His jacket is wet\" means his jacket is…","options":["new","warm","full of water from the rain","too small"],"answer_index":2,"explanation":"\"Then the rain starts… Jasur's jacket is wet.\" The rain makes it wet.","skill":"reading.vocabulary"}]}$seed$::jsonb) r
    returning id into v_parent_id;

    insert into public.learning_content_registry_items (
      product_id, language_id, source_record_id, service_key, content_type, source_table, source_ref, title, description,
