      jsonb_build_object('seeded_by', v_seed)
    from jsonb_populate_record(null::public.learning_content_registry_items, $seed${"service_key":"reading","content_type":"reading.article","source_table":"reading_articles","source_ref":"a1-a-rainy-day-in-tashkent","title":"A Rainy Day in Tashkent","skill_key":"reading","cefr_level":"A1","difficulty":0.2,"status":"published","description":"Jasur has no umbrella on a rainy morning, but a kind woman at the bus stop helps him.","subskill_keys":["reading.gist","reading.detail","reading.inference","vocabulary.context"],"estimated_minutes":4,"learning_objective":"Jasur has no umbrella on a rainy morning, but a kind woman at the bus stop helps him.","tags":["Everyday","weather"],"payload_json":{"tone":"mint","is_hot":false,"question_count":5}}$seed$::jsonb) r
    on conflict (language_id, service_key, content_type, source_ref) do update set
