    from jsonb_populate_record(null::public.learning_content_registry_items, $seed${"service_key":"reading","content_type":"reading.article","source_table":"reading_articles","source_ref":"a1-city-library-opening-hours","title":"City Library: Opening Hours","skill_key":"reading","cefr_level":"A1","difficulty":0.2,"status":"published","description":"A notice gives the library's opening hours, its rules and how to get a free library card.","subskill_keys":["reading.gist","reading.detail","reading.inference","vocabulary.context"],"estimated_minutes":4,"learning_objective":"A notice gives the library's opening hours, its rules and how to get a free library card.","tags":["Everyday","library notice"],"payload_json":{"tone":"sky","is_hot":false,"question_count":5}}$seed$::jsonb) r
