  -- reading: a1-messages-with-a-new-neighbour (A1)
  if exists (select 1 from public.reading_articles where product_id = v_product_reading and language_id = v_en_id and slug = 'a1-messages-with-a-new-neighbour') then
    raise notice 'skipped existing reading item %', 'a1-messages-with-a-new-neighbour';
  else
    insert into public.reading_articles (slug, title, level, status, sort_order, metadata, summary, content_markdown, category, theme, tone, read_time_minutes, is_hot, questions, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.summary, r.content_markdown, r.category, r.theme, r.tone, r.read_time_minutes, r.is_hot, r.questions, v_product_reading, v_en_id
    from jsonb_populate_record(null::public.reading_articles, $seed${"slug":"a1-messages-with-a-new-neighbour","title":"Messages with a New Neighbour","level":"A1","status":"published","sort_order":200,"metadata":{"genre":"message","writing_tone":"friendly","word_count":124},"summary":"Two neighbours write messages about a parcel, a lift that doesn't work, and tea on Saturday.","content_markdown":"**Nilufar:** Hi! I'm Nilufar from flat 12. I'm your new neighbour. I have a parcel for you. The delivery man can't find you today.\n\n**Kamola:** Oh, thank you, Nilufar! I'm at work now. I can come at seven o'clock. Is that OK?\n\n**Nilufar:** Yes, that's fine. I'm at home all evening. My flat is on the fourth floor, next to the lift.\n\n**Kamola:** Great. Is the lift OK today? Yesterday it was broken.\n\n**Nilufar:** No, it's broken again. Sorry, you need the stairs!\n\n**Kamola:** No problem. I like the stairs. They are good exercise!\n\n**Nilufar:** Ha ha. Would you like tea with me on Saturday? I have a big family, and we always have sweets.\n\n**Kamola:** Yes, I'd love to! See you at seven.","category":"Everyday","theme":"neighbours","tone":"lavender","read_time_minutes":2,"is_hot":false,"questions":[{"id":"q1","type":"mcq","prompt":"Why does Nilufar write to Kamola first?","options":["She has Kamola's parcel.","She wants to buy Kamola's flat.","She needs help with the lift.","She is Kamola's teacher."],"answer_index":0,"explanation":"\"I have a parcel for you.\"","skill":"reading.main_idea"},{"id":"q2","type":"mcq","prompt":"When can Kamola come to Nilufar's flat?","options":["Now","On Saturday morning","At seven o'clock","Tomorrow"],"answer_index":2,"explanation":"\"I can come at seven o'clock.\"","skill":"reading.detail"},{"id":"q3","type":"mcq","prompt":"Where is Nilufar's flat?","options":["On the first floor","On the fourth floor, next to the lift","In flat 4","Next to Kamola's office"],"answer_index":1,"explanation":"\"My flat is on the fourth floor, next to the lift.\"","skill":"reading.detail"},{"id":"q4","type":"mcq","prompt":"How will Kamola go up to Nilufar's flat?","options":["By lift","With the delivery man","She will not go.","By the stairs"],"answer_index":3,"explanation":"The lift is \"broken again\", and Kamola says \"No problem. I like the stairs.\"","skill":"reading.inference"},{"id":"q5","type":"mcq","prompt":"The lift is \"broken\". This means…","options":["it is new","it doesn't work","it is very fast","it is closed on Saturday"],"answer_index":1,"explanation":"Kamola asks if the lift is OK, and Nilufar says \"No, it's broken again\": it doesn't work.","skill":"reading.vocabulary"}]}$seed$::jsonb) r
