  else
    insert into public.reading_articles (slug, title, level, status, sort_order, metadata, summary, content_markdown, category, theme, tone, read_time_minutes, is_hot, questions, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.summary, r.content_markdown, r.category, r.theme, r.tone, r.read_time_minutes, r.is_hot, r.questions, v_product_reading, v_en_id
    from jsonb_populate_record(null::public.reading_articles, $seed${"slug":"a2-the-evening-the-lights-went-out","title":"The Evening the Lights Went Out","level":"A2","status":"published","sort_order":200,"metadata":{"genre":"story","writing_tone":"warm","word_count":176},"summary":"During a power cut in a mahalla, neighbours share light, tea and food, and a boy sees his street differently.","content_markdown":"Last winter, on a cold evening in January, the lights in our mahalla suddenly went out. I was doing my maths homework, and my mother was cooking soup. Everything was dark and very quiet. The fridge stopped, the TV stopped, and my phone had only ten per cent battery.\n\nAt first, I was a bit scared. Then I heard voices outside. Our neighbour, Uncle Rustam, was in the street with a big torch. \"Is everyone OK?\" he asked. His wife brought candles for the old woman who lives alone at the end of the street.\n\nOur gas cooker still worked, so my mother finished the soup and invited three families to eat with us. We sat together in the kitchen with candles on the table. The adults told stories about their childhood, and the children played word games.\n\nThe electricity came back after three hours. Everyone cheered, but I felt a little sad. It was a better evening than most evenings with the TV. Now, I know the names of all the children on our street.","category":"Society","theme":"community","tone":"peach","read_time_minutes":2,"is_hot":false,"questions":[{"id":"q1","type":"mcq","prompt":"What is the main idea of the story?","options":["Power cuts are dangerous in winter.","The writer couldn't finish his homework.","A power cut brought the neighbours together.","The writer's mother is a good cook."],"answer_index":2,"explanation":"The neighbours helped each other and ate together, and the writer says \"It was a better evening than most evenings with the TV.\"","skill":"reading.main_idea"},{"id":"q2","type":"mcq","prompt":"What was the writer doing when the lights went out?","options":["Watching TV","Cooking soup","Playing word games","Doing his maths homework"],"answer_index":3,"explanation":"\"I was doing my maths homework, and my mother was cooking soup.\"","skill":"reading.detail"},{"id":"q3","type":"mcq","prompt":"Why could his mother finish the soup?","options":["The gas cooker still worked.","Uncle Rustam had a torch.","The electricity came back quickly.","She cooked it with candles."],"answer_index":0,"explanation":"\"Our gas cooker still worked, so my mother finished the soup.\"","skill":"reading.detail"},{"id":"q4","type":"mcq","prompt":"Why did the writer feel \"a little sad\" when the electricity came back?","options":["His phone was broken.","He enjoyed the evening with the neighbours.","He was still scared of the dark.","The soup was cold."],"answer_index":1,"explanation":"He says \"It was a better evening than most evenings with the TV\", so he didn't want it to end.","skill":"reading.inference"},{"id":"q5","type":"mcq","prompt":"\"Everyone cheered.\" When people cheer, they…","options":["shout happily","go to sleep","feel angry","start to cry"],"answer_index":0,"explanation":"People cheered because \"The electricity came back\": they shouted because they were happy.","skill":"reading.vocabulary"}]}$seed$::jsonb) r
