    from jsonb_populate_record(null::public.learning_content_registry_items, $seed${"service_key":"reading","content_type":"reading.article","source_table":"reading_articles","source_ref":"c1-the-aral-sea-and-the-limits-of-control","title":"The Aral Sea and the Limits of Control","skill_key":"reading","cefr_level":"C1","difficulty":0.75,"status":"published","description":"The shrinking of the Aral Sea is often told as a story of disaster, but it is also a lesson about how confidently people plan, and how slowly they learn.","subskill_keys":["reading.gist","reading.detail","reading.inference","vocabulary.context"],"estimated_minutes":8,"learning_objective":"The shrinking of the Aral Sea is often told as a story of disaster, but it is also a lesson about how confidently people plan, and how slowly they learn.","tags":["Environment","water and planning"],"payload_json":{"tone":"sand","is_hot":false,"question_count":5}}$seed$::jsonb) r
