    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"a1-at-the-pharmacy","title":"At the Pharmacy","level":"A1","status":"published","sort_order":200,"metadata":{"format":"dialogue","script_type":"dialogue","speakers":["Pharmacist","Madina"]},"summary":"Madina asks a pharmacist for something for a headache and learns how often to take the tablets.","transcript_text":"Pharmacist: Good morning. How can I help you?\nMadina: Hi. I have a bad headache. Do you have something for it?\nPharmacist: Yes, these tablets are good for headaches. Do you have a temperature?\nMadina: No, I don't. I'm just very tired.\nPharmacist: OK. Take one tablet after a meal, with some water. You can take one every six hours, but not more than four a day.\nMadina: Every six hours. OK. How much is it?\nPharmacist: It's twelve thousand som.\nMadina: Here you are. Thank you!\nPharmacist: You're welcome. Drink lots of water and get some sleep.","category":"Health","accent":"general","speed_label":"slow","speed_wpm":110,"duration_seconds":49,"audio_url":null,"focus_skill":"detail","tags":["health","pharmacy","dialogue"],"questions":[{"id":"q1","type":"mcq","prompt":"What is Madina's problem?","options":["She has a temperature.","She can't sleep.","She has a bad headache.","She has a sore throat."],"answer_index":2,"explanation":"Madina says: \"I have a bad headache.\""},{"id":"q2","type":"mcq","prompt":"How often can she take a tablet?","options":["Every four hours","Every six hours","Once a day","Every two hours"],"answer_index":1,"explanation":"\"You can take one every six hours, but not more than four a day.\""},{"id":"q3","type":"mcq","prompt":"How much are the tablets?","options":["Twelve thousand som","Ten thousand som","Twenty thousand som","Two thousand som"],"answer_index":0,"explanation":"\"It's twelve thousand som.\""},{"id":"q4","type":"mcq","prompt":"What does the pharmacist tell her to do?","options":["Go to a doctor","Eat nothing today","Take two tablets at once","Drink lots of water and get some sleep"],"answer_index":3,"explanation":"\"Drink lots of water and get some sleep.\""}]}$seed$::jsonb) r
