    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"a2-joining-a-gym","title":"Joining a Gym","level":"A2","status":"published","sort_order":200,"metadata":{"format":"dialogue","script_type":"dialogue","speakers":["Timur","Nilufar"]},"summary":"Nilufar compares two gym memberships, asks about classes and chooses the one that fits her working hours.","transcript_text":"Timur: Hi there, welcome to City Fit. Are you interested in joining?\nNilufar: Yes, I am. Can you tell me about the memberships?\nTimur: Sure. We have two options. The basic one is two hundred thousand som a month, and you can come from seven in the morning until four in the afternoon.\nNilufar: Hmm, I work until five, so that's no good for me.\nTimur: Then the full membership is better. It's three hundred thousand a month, and you can come any time from six in the morning to eleven at night. It also includes group classes.\nNilufar: What kind of classes do you have?\nTimur: Yoga on Monday and Wednesday evenings, and a dance class on Saturday mornings.\nNilufar: Oh, I'd love to try yoga. Do I need to bring anything?\nTimur: Just comfortable clothes and a towel. We have mats here.\nNilufar: Great. I'll take the full membership, please.","category":"Health","accent":"general","speed_label":"slow","speed_wpm":125,"duration_seconds":68,"audio_url":null,"focus_skill":"detail","tags":["sport","gym","dialogue"],"questions":[{"id":"q1","type":"mcq","prompt":"Why is the basic membership no good for Nilufar?","options":["It's too expensive.","She works until five.","It has no classes on Saturday.","It's only for students."],"answer_index":1,"explanation":"\"The basic one ... until four in the afternoon.\" Nilufar: \"I work until five, so that's no good for me.\""},{"id":"q2","type":"mcq","prompt":"How much is the full membership?","options":["200,000 som a month","250,000 som a month","300,000 som a month","300,000 som a year"],"answer_index":2,"explanation":"\"It's three hundred thousand a month.\""},{"id":"q3","type":"mcq","prompt":"When are the yoga classes?","options":["Monday and Wednesday evenings","Saturday mornings","Every morning at six","Tuesday and Thursday evenings"],"answer_index":0,"explanation":"\"Yoga on Monday and Wednesday evenings, and a dance class on Saturday mornings.\""},{"id":"q4","type":"mcq","prompt":"What does she need to bring?","options":["A yoga mat","A photo and her passport","Nothing at all","Comfortable clothes and a towel"],"answer_index":3,"explanation":"\"Just comfortable clothes and a towel. We have mats here.\""}]}$seed$::jsonb) r
