    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"a2-making-a-doctors-appointment","title":"Making a Doctor's Appointment","level":"A2","status":"published","sort_order":200,"metadata":{"format":"dialogue","script_type":"dialogue","speakers":["Receptionist","Jasur"]},"summary":"A student abroad phones a clinic about a sore throat and changes the first appointment time he is offered.","transcript_text":"Receptionist: Good morning, Riverside Medical Centre. How can I help?\nJasur: Hello. I'd like to make an appointment with a doctor, please.\nReceptionist: Of course. Are you registered with us?\nJasur: Yes, I registered last month. I'm a student at the university.\nReceptionist: Can I have your name and date of birth?\nJasur: It's Jasur Aliyev, and I was born on the fifth of March, two thousand and four.\nReceptionist: Thank you. And what's the problem?\nJasur: I've had a sore throat for a week, and now I have a cough too.\nReceptionist: I see. The first appointment is on Thursday at a quarter past eleven. Is that OK?\nJasur: Thursday's difficult, I have an exam. Is there anything earlier?\nReceptionist: Let me check. Yes, there's one tomorrow at twenty to nine with Dr Patel.\nJasur: That's perfect, thank you.\nReceptionist: Please come ten minutes early. See you tomorrow.","category":"Health","accent":"general","speed_label":"slow","speed_wpm":125,"duration_seconds":65,"audio_url":null,"focus_skill":"detail","tags":["health","phone call","study abroad","dialogue"],"questions":[{"id":"q1","type":"mcq","prompt":"How long has Jasur had a sore throat?","options":["Since yesterday","For three days","For a week","For a month"],"answer_index":2,"explanation":"\"I've had a sore throat for a week, and now I have a cough too.\""},{"id":"q2","type":"mcq","prompt":"Why can't he go on Thursday?","options":["He has an exam.","He works on Thursdays.","He is travelling.","The doctor is busy."],"answer_index":0,"explanation":"\"Thursday's difficult, I have an exam.\""},{"id":"q3","type":"mcq","prompt":"When is his appointment?","options":["Thursday at a quarter past eleven","Tomorrow at twenty to nine","Tomorrow at nine o'clock","Today at twenty to nine"],"answer_index":1,"explanation":"\"There's one tomorrow at twenty to nine with Dr Patel.\" \"That's perfect.\""},{"id":"q4","type":"mcq","prompt":"What does the receptionist ask him to do?","options":["Bring his passport","Call again tomorrow","Pay before he comes","Come ten minutes early"],"answer_index":3,"explanation":"\"Please come ten minutes early.\""}]}$seed$::jsonb) r
