    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"b1-radio-weekend-events-in-the-city","title":"What's On This Weekend","level":"B1","status":"published","sort_order":200,"metadata":{"format":"monologue","script_type":"radio"},"summary":"A local radio guide to the weekend: a book fair, a street food festival, an open-air concert and the weather.","transcript_text":"And now it's time for our weekend guide. There's plenty going on around the city, so here are our top picks. On Saturday morning, Green Park is holding a family book fair from ten until two. Local writers will read from their new books, and there's a free drawing workshop for children. Bring some old books if you'd like to swap them. If food is more your thing, don't miss the street food festival on the new boulevard. It runs all weekend, from noon until late, with dishes from somsa and shashlik to Korean and Turkish food. Entry is free, but it gets very busy in the evenings, so go early if you can. For music fans, there's an open-air jazz concert on Sunday evening at seven in the City Garden. Tickets cost fifty thousand som and you can buy them online. And finally, the weather. It's going to be sunny and warm on Saturday, but there's a chance of rain on Sunday afternoon. So keep an umbrella handy if you're going to the concert. Have a great weekend!","category":"Culture","accent":"general","speed_label":"natural","speed_wpm":140,"duration_seconds":77,"audio_url":null,"focus_skill":"detail","tags":["radio","events","weekend","city"],"questions":[{"id":"q1","type":"mcq","prompt":"What can children do at the book fair?","options":["Meet famous actors","Join a free drawing workshop","Buy books for half price","Write their own stories"],"answer_index":1,"explanation":"\"There's a free drawing workshop for children.\""},{"id":"q2","type":"mcq","prompt":"Why should people bring old books?","options":["To sell them","To give them to a library","To swap them","To get a free ticket"],"answer_index":2,"explanation":"\"Bring some old books if you'd like to swap them.\""},{"id":"q3","type":"mcq","prompt":"What advice does the presenter give about the food festival?","options":["Go early, because it's busy in the evenings.","Buy tickets online.","Bring your own food.","Only go on Sunday."],"answer_index":0,"explanation":"\"It gets very busy in the evenings, so go early if you can.\""},{"id":"q4","type":"mcq","prompt":"Why might concert-goers need an umbrella?","options":["The concert is next to a lake.","It will be very sunny on Saturday.","The garden has no trees.","It may rain on Sunday afternoon."],"answer_index":3,"explanation":"\"There's a chance of rain on Sunday afternoon. So keep an umbrella handy if you're going to the concert.\""}]}$seed$::jsonb) r
