    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"b1-tech-support-call","title":"My Laptop Won't Charge","level":"B1","status":"published","sort_order":200,"metadata":{"format":"dialogue","script_type":"dialogue","speakers":["Sam","Rustam"]},"summary":"A customer calls tech support because his laptop isn't charging, and together they find the cause step by step.","transcript_text":"Sam: Hello, you're through to TechHelp support. My name's Sam. How can I help you today?\nRustam: Hi, Sam. My laptop isn't charging. I plugged it in last night, and this morning the battery was still at five percent.\nSam: OK, let's try to sort it out. First, when you plug the charger in, does the little light on the side come on?\nRustam: No, nothing happens at all.\nSam: Right. Have you tried a different socket? Sometimes the problem is the socket, not the laptop.\nRustam: Oh, I haven't. Hold on. No, still nothing.\nSam: OK. Could you check the cable for any damage, especially near the ends?\nRustam: Actually, yes. It's a bit bent near the plug. My cat likes chewing cables, so...\nSam: That's probably the cause, then. The good news is that your laptop is likely fine. You just need a new charger.\nRustam: Phew. Is it covered by the warranty?\nSam: I'm afraid the warranty doesn't cover damage to cables. But I can order a new one for you, and delivery is free. It should arrive in two or three working days.\nRustam: That's fine. Thanks for your help.","category":"Work and Study","accent":"general","speed_label":"natural","speed_wpm":140,"duration_seconds":78,"audio_url":null,"focus_skill":"detail","tags":["technology","phone call","problem solving","dialogue"],"questions":[{"id":"q1","type":"mcq","prompt":"What did Rustam notice this morning?","options":["The laptop screen was broken.","The battery was still at five percent.","The laptop was very hot.","The charger light was red."],"answer_index":1,"explanation":"\"This morning the battery was still at five percent.\""},{"id":"q2","type":"mcq","prompt":"What does Sam ask Rustam to try first?","options":["To restart the laptop","To buy a new battery","To check if the light on the side comes on","To call back later"],"answer_index":2,"explanation":"\"Does the little light on the side come on?\""},{"id":"q3","type":"mcq","prompt":"What is probably causing the problem?","options":["A damaged cable","A broken socket","An old battery","A software problem"],"answer_index":0,"explanation":"The cable is \"a bit bent near the plug\" and Sam says \"That's probably the cause\"."},{"id":"q4","type":"mcq","prompt":"Why does Rustam say \"Phew\"?","options":["He has to pay a lot of money.","The call is very long.","His cat is safe.","He is relieved that the laptop itself is probably fine."],"answer_index":3,"explanation":"Sam says \"your laptop is likely fine. You just need a new charger\", so Rustam feels relieved."},{"id":"q5","type":"mcq","prompt":"What does Sam say about the warranty?","options":["It covers everything.","It doesn't cover damage to cables.","It finished last year.","It only covers the screen."],"answer_index":1,"explanation":"\"I'm afraid the warranty doesn't cover damage to cables.\""}]}$seed$::jsonb) r
