  -- listening: c2-debate-should-ai-write-our-emails (C2)
  if exists (select 1 from public.listening_items where product_id = v_product_listening and language_id = v_en_id and slug = 'c2-debate-should-ai-write-our-emails') then
    raise notice 'skipped existing listening item %', 'c2-debate-should-ai-write-our-emails';
  else
    insert into public.listening_items (slug, title, level, status, sort_order, metadata, summary, transcript_text, category, accent, speed_label, speed_wpm, duration_seconds, audio_url, focus_skill, tags, questions, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.summary, r.transcript_text, r.category, r.accent, r.speed_label, r.speed_wpm, r.duration_seconds, r.audio_url, r.focus_skill, r.tags, r.questions, v_product_listening, v_en_id
    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"c2-debate-should-ai-write-our-emails","title":"Debate: Should AI Write Our Emails?","level":"C2","status":"published","sort_order":200,"metadata":{"format":"dialogue","script_type":"dialogue","speakers":["Sophie","Rustam"]},"summary":"Two commentators argue about using AI assistants to write emails: efficiency against authenticity, and what happens to trust when any message might be generated.","transcript_text":"Sophie: Let me put my cards on the table. I use an AI assistant for most of my work emails now, and I don't feel the slightest bit guilty about it.\nRustam: I'm not asking you to feel guilty. I'm asking what we lose when nobody actually writes to anybody any more.\nSophie: Oh, come on, most emails aren't heartfelt letters. They're 'please find attached' and 'just following up'. If a machine can draft those in seconds, I've got more time for the work that matters.\nRustam: For routine messages, fine, I'll grant you that. But the line isn't nearly as clear as you're making it sound. A colleague who's just lost their job, a client who's upset, a thank-you to someone who went out of their way: those are emails too.\nSophie: And I'd write those myself. Nobody's suggesting we outsource sympathy.\nRustam: Aren't they, though? Once the tool is open and the draft is sitting there, looking perfectly reasonable, the temptation is just to hit send. Habits creep.\nSophie: That's a fair worry, but it's an argument for using the tool thoughtfully, not for refusing it altogether.\nRustam: My other concern is that people will start to discount everything they receive. If any message might have been generated, a kind word means less, because you can't be sure anyone actually meant it.\nSophie: Hmm, that's more persuasive, I'll admit. I've had messages from friends recently that were so smooth I found myself wondering whether they'd written a single word of them. And honestly, it took some of the warmth out. Maybe the answer is simply honesty, being open about when we've used it.\nRustam: Now that I could live with.","category":"Technology","accent":"general","speed_label":"fast","speed_wpm":170,"duration_seconds":96,"audio_url":null,"focus_skill":"inference","tags":["AI","debate","communication","dialogue"],"questions":[{"id":"q1","type":"mcq","prompt":"What is Sophie's position at the start of the debate?","options":["She sees nothing wrong with using AI for her work emails.","She uses AI only for personal messages.","She feels guilty about using AI.","She thinks AI emails are badly written."],"answer_index":0,"explanation":"\"I use an AI assistant for most of my work emails now, and I don't feel the slightest bit guilty about it.\""},{"id":"q2","type":"mcq","prompt":"Which emails does Rustam think need a personal touch?","options":["Emails with attachments","Follow-up reminders","Messages involving feelings, such as sympathy or thanks","Messages to large groups"],"answer_index":2,"explanation":"\"A colleague who's just lost their job, a client who's upset, a thank-you to someone who went out of their way: those are emails too.\""},{"id":"q3","type":"mcq","prompt":"What does Rustam mean by 'habits creep'?","options":["People get tired of writing emails.","The tool slowly gets better.","Companies will ban AI tools.","People gradually use the tool even where they meant not to."],"answer_index":3,"explanation":"\"Once the tool is open and the draft is sitting there... the temptation is just to hit send. Habits creep.\""},{"id":"q4","type":"mcq","prompt":"Which of Rustam's arguments does Sophie find most convincing?","options":["That AI emails take too long to check","That kind words may mean less if any message could be generated","That routine emails are important","That AI makes grammar mistakes"],"answer_index":1,"explanation":"After Rustam says \"a kind word means less\", Sophie answers: \"That's more persuasive, I'll admit.\""},{"id":"q5","type":"mcq","prompt":"How does the debate end?","options":["Sophie promises to stop using AI.","Rustam agrees that AI should write all emails.","They reach partial agreement about being open when AI is used.","They decide the question cannot be answered."],"answer_index":2,"explanation":"Sophie: \"Maybe the answer is simply honesty, being open about when we've used it.\" Rustam: \"Now that I could live with.\""}]}$seed$::jsonb) r
