    insert into public.listening_items (slug, title, level, status, sort_order, metadata, summary, transcript_text, category, accent, speed_label, speed_wpm, duration_seconds, audio_url, focus_skill, tags, questions, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.summary, r.transcript_text, r.category, r.accent, r.speed_label, r.speed_wpm, r.duration_seconds, r.audio_url, r.focus_skill, r.tags, r.questions, v_product_listening, v_en_id
    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"c2-podcast-the-art-of-the-apology","title":"Podcast: The Art of the Apology","level":"C2","status":"published","sort_order":200,"metadata":{"format":"monologue","script_type":"podcast"},"summary":"A podcast host explains why non-apologies fail and sets out four steps of a genuine apology, from naming what you did to not demanding forgiveness.","transcript_text":"Hello, and welcome to the last episode of the season. Today I want to talk about something we all do badly at some point: apologising. We've all heard the non-apology. 'I'm sorry if anyone was offended.' 'Mistakes were made.' Notice the grammar there. The 'if' turns the hurt into a hypothetical, and the passive voice quietly removes the person who made the mistake from the sentence altogether. So what does a genuine apology involve? I'd suggest four things, and the order matters. First, name what you did, specifically and without softening it. Not 'things got a bit out of hand', but 'I shouted at you in front of your colleagues'. Second, acknowledge the effect it had, and resist the urge to explain your intentions too soon. The moment you say 'but I was really stressed', the apology starts to become a defence. Third, say what you'll do differently, and make it concrete enough that the other person could actually check. And fourth, which is by far the hardest part, don't demand forgiveness. An apology that comes with a deadline, 'so, are we fine now?', is really a request for the apologiser's own discomfort to end. Forgiveness is something the other person may offer in their own time, or not at all. Interestingly, in many families and communities, an apology is shown through actions as much as words: a visit, a shared meal, help offered without being asked. I think there's real wisdom in that, because in the end an apology is judged less by how well it's phrased than by what happens next.","category":"Society","accent":"general","speed_label":"natural","speed_wpm":170,"duration_seconds":93,"audio_url":null,"focus_skill":"inference","tags":["relationships","communication","podcast","language"],"questions":[{"id":"q1","type":"mcq","prompt":"What does the host say about the sentence 'Mistakes were made'?","options":["It is the most polite form of apology.","Its grammar hides who made the mistake.","It is too direct.","It is only used in business."],"answer_index":1,"explanation":"\"The passive voice quietly removes the person who made the mistake from the sentence altogether.\""},{"id":"q2","type":"mcq","prompt":"Why does the host warn against explaining your intentions too soon?","options":["It takes too much time.","The other person will not believe you.","It makes the apology too short.","It can turn the apology into a defence."],"answer_index":3,"explanation":"\"The moment you say 'but I was really stressed', the apology starts to become a defence.\""},{"id":"q3","type":"mcq","prompt":"What should a promise to change be like?","options":["Specific enough to be checked","As general as possible","Made in writing","Made in front of other people"],"answer_index":0,"explanation":"\"Make it concrete enough that the other person could actually check.\""},{"id":"q4","type":"mcq","prompt":"What is the host's view of asking 'so, are we fine now?'","options":["It shows real respect.","It is the best way to end an apology.","It puts the apologiser's comfort first.","It is necessary in most cultures."],"answer_index":2,"explanation":"It \"is really a request for the apologiser's own discomfort to end.\""},{"id":"q5","type":"mcq","prompt":"What is the host's overall message?","options":["Apologies should be as short as possible.","Good grammar is the key to a good apology.","Forgiveness should be asked for quickly.","An apology is judged mainly by what the person does afterwards."],"answer_index":3,"explanation":"\"An apology is judged less by how well it's phrased than by what happens next.\""}]}$seed$::jsonb) r
