    from jsonb_populate_record(null::public.immersion_missions, $seed${"slug":"b1-reporting-a-broken-heater-in-the-dorm","title":"Reporting a broken heater in the dorm","level":"B1","status":"published","sort_order":200,"metadata":{},"context_text":"It is November and you are studying in Poland. The heater in your dormitory room stopped working three days ago, and the room is very cold at night. You reported it at reception on Monday, but nothing has happened.","objective_text":"Understand the maintenance rules, find out why nobody came, report the problem properly in writing, and follow it up by phone.","mission_type":"problem_solving","target_vocabulary":["maintenance request","reference number","urgent","technician","temporary heater","follow up"],"target_grammar":"present perfect with since / for and already / yet (It hasn't worked since Monday. Nobody has come yet.)","cultural_note":"Many housing offices only act on requests that are written down with a reference number. A spoken complaint at reception is often forgotten, so it is normal to put it in writing and politely mention the dates.","success_conditions_json":["Understand how and when to report a repair","Find out why the first report did not work","Write a complete maintenance request with dates and the room number","Follow up by phone and ask for a temporary solution"],"skill_mix":["reading","listening","writing","speaking"]}$seed$::jsonb) r
