    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the housing office notice","instructions":"Read the notice in the corridor. Then answer the questions.","prompt_text":"REPAIRS IN YOUR ROOM\nAll repairs must be reported using the online maintenance form. Reception cannot create requests.\nAfter you send the form, you will receive a reference number by email.\nUrgent problems (no water, no heating in winter, electrical danger) are dealt with within 48 hours. Other problems: within 7 working days.\nPlease say when a technician can enter your room.","expected_answer_json":{"questions":[{"id":"q1","prompt":"How must students report repairs?","options":["At reception","With the online form","By calling a technician"],"answer":1,"explanation":"\"All repairs must be reported using the online maintenance form. Reception cannot create requests.\""},{"id":"q2","prompt":"Why is your problem urgent?","options":["There is no heating in winter","There is no water","It is an electrical danger"],"answer":0,"explanation":"\"No heating in winter\" is listed as an urgent problem."},{"id":"q3","prompt":"What should you include in the form?","options":["Your bank details","When a technician can come in","A photo of your student card"],"answer":1,"explanation":"\"Please say when a technician can enter your room.\""}]},"target_skill_key":"reading.detail","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
