    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to the receptionist","instructions":"You go back to reception to ask what happened. Listen to the receptionist. Then answer the questions.","prompt_text":"Oh, I'm really sorry about that. I remember you, but I'm afraid I can't send repair requests from here any more. They changed the system last month, so everything goes through the online form now. If you fill it in today and tick 'urgent', someone should come within two days. And listen, if it's really cold tonight, we have a few small electric heaters in the storage room. You can borrow one if you leave your student card with us.","expected_answer_json":{"questions":[{"id":"q1","prompt":"Why did nothing happen after your first report?","options":["The technician was ill","Reception can't send repair requests any more","Your room number was wrong"],"answer":1,"explanation":"\"I can't send repair requests from here any more. They changed the system last month.\""},{"id":"q2","prompt":"What can you do tonight?","options":["Sleep in another room","Borrow a small electric heater","Get a refund for the night"],"answer":1,"explanation":"\"We have a few small electric heaters... You can borrow one.\""}]},"target_skill_key":"listening.detail","estimated_minutes":4,"status":"published","metadata":{"accent":"gb"}}$seed$::jsonb) r;
