    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"writing","step_type":"reply","title":"Fill in the maintenance form","instructions":"Write the description for the online form. Give your room number, describe the problem and since when, say it is urgent, and say when a technician can come in.","prompt_text":"Maintenance request – Description of the problem:","expected_answer_json":{"goal":"Write a complete, clear maintenance request.","points":[{"label":"give the room number","any":["room","block","flat","number"]},{"label":"describe the problem and since when","any":["heater","heating","radiator","since","for three days","monday","not working","doesn't work","broken","stopped"]},{"label":"say it is urgent","any":["urgent","cold","freezing","as soon as possible","asap","quickly"]},{"label":"say when the technician can come in","any":["can enter","can come","any time","anytime","morning","afternoon","after","between","available","i'm in"]}],"model_answer":"Room 214, Block C. The heater in my room has not worked since Monday, so for three days now. It doesn't get warm at all, and the room is very cold at night. I reported it at reception on Monday, but I have now learned that I must use this form. This is urgent because there is no heating. A technician can enter my room any time, even when I am not there."},"target_skill_key":"writing.task_completion","estimated_minutes":7,"status":"published","metadata":{}}$seed$::jsonb) r;
