    from jsonb_populate_record(null::public.immersion_missions, $seed${"slug":"b1-starting-an-online-study-group","title":"Starting an online study group","level":"B1","status":"published","sort_order":200,"metadata":{},"context_text":"You are preparing for an international English exam with an online course. The final test is in six weeks. You want to start a small online study group with three classmates who live in different cities and time zones.","objective_text":"Understand the course rules for group work, agree a time that suits everyone, invite your classmates in writing and explain the plan in the first call.","mission_type":"study","target_vocabulary":["study group","time zone","schedule","take turns","shared document","deadline"],"target_grammar":"suggestions and making plans (How about…? Why don't we…? Let's…, We could…)","cultural_note":"In online groups across time zones, always give times with the city or time zone (\"8 pm Tashkent time\"). Giving everyone a clear role from the start stops one person from doing all the work.","success_conditions_json":["Understand what the course allows in group work","Find a time that works for every member","Write a clear invitation with time, time zone and roles","Explain the plan and check everyone agrees"],"skill_mix":["reading","listening","writing","speaking"]}$seed$::jsonb) r
