    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the course forum post","instructions":"Read this post from your course tutor. Then answer the questions.","prompt_text":"Study groups – a few rules\nWe really encourage you to practise together! You may share notes, practise speaking and check each other's essays. However, the weekly graded tasks must be your own work: please don't share answers to these.\nGroups of three to five work best. If you start a group, post the day and time in this forum so other students can join.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What must students NOT do in study groups?","options":["Practise speaking together","Share answers to the graded tasks","Check each other's essays"],"answer":1,"explanation":"\"The weekly graded tasks must be your own work: please don't share answers to these.\""},{"id":"q2","prompt":"What does the tutor ask group organisers to do?","options":["Post the day and time in the forum","Send the tutor a list of members","Keep the group to two people"],"answer":0,"explanation":"\"Post the day and time in this forum so other students can join.\""}]},"target_skill_key":"reading.detail","estimated_minutes":3,"status":"published","metadata":{}}$seed$::jsonb) r;
