    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the offer letter","instructions":"Read the main part of the offer letter. Then answer the questions.","prompt_text":"Dear Sardor,\nWe are delighted to offer you the position of Junior Backend Developer.\n- Start date: 1 March\n- Gross monthly salary: as discussed in your final interview\n- Probation period: three months, after which your salary will be reviewed\n- Benefits: private health insurance, a learning budget for courses and conferences, two remote days per week\nPlease let us know your decision within five working days. If you have any questions about the offer, Nilufar from our recruitment team will be happy to discuss them.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What happens at the end of the probation period?","options":["The contract ends automatically","The salary is reviewed","The remote days are removed"],"answer":1,"explanation":"\"Probation period: three months, after which your salary will be reviewed.\""},{"id":"q2","prompt":"Which benefit could help Sardor's career development?","options":["Health insurance","The learning budget","The start date"],"answer":1,"explanation":"\"A learning budget for courses and conferences\" supports professional development."},{"id":"q3","prompt":"What is the deadline for his decision?","options":["Five working days","Three months","1 March"],"answer":0,"explanation":"\"Please let us know your decision within five working days.\""}]},"target_skill_key":"reading.detail","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to a friend's advice","instructions":"Your friend Jamshid has worked at the same company for two years. Listen to his advice. Then answer the questions.","prompt_text":"Honestly, you should definitely ask. They expect it. From what I've seen, the base salary for juniors is set in bands, so they can usually move a little, but not a lot. Where they're much more flexible is the probation review. When I joined, I asked them to write down in the contract that my salary would go up after three months if my review went well, and they agreed straight away. The other thing people forget is the learning budget. If there's a certification you want, ask them to confirm it's covered. Just don't make it sound like an ultimatum.","expected_answer_json":{"questions":[{"id":"q1","prompt":"According to Jamshid, how flexible is the base salary?","options":["Not at all","A little, but not a lot","Completely flexible"],"answer":1,"explanation":"\"They can usually move a little, but not a lot.\""},{"id":"q2","prompt":"What did Jamshid get written into his contract?","options":["A raise after a good three-month review","Four remote days a week","A higher starting salary"],"answer":0,"explanation":"\"My salary would go up after three months if my review went well, and they agreed.\""},{"id":"q3","prompt":"What does he warn against?","options":["Asking about the learning budget","Sounding as if you are giving an ultimatum","Replying too slowly"],"answer":1,"explanation":"\"Just don't make it sound like an ultimatum.\""}]},"target_skill_key":"listening.detail","estimated_minutes":4,"status":"published","metadata":{"accent":"gb"}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"writing","step_type":"reply","title":"Reply to the recruiter","instructions":"Write an email to Nilufar. Thank her for the offer, show you are keen, ask politely about flexibility on the salary with a reason, and suggest an alternative such as a written review after probation.","prompt_text":"To: Nilufar (Recruitment)\nSubject: Re: Offer – Junior Backend Developer","expected_answer_json":{"goal":"Make a polite, reasoned counter-proposal while showing commitment.","points":[{"label":"thank them and show enthusiasm","any":["thank*","delighted","excited","pleased","keen","look forward","happy to"]},{"label":"ask about salary flexibility","any":["flexib*","salary","closer to","slightly higher","reconsider","was wondering","possible to"]},{"label":"give a reason","any":["because","since","as i","experience","project*","skills","market","course"]},{"label":"suggest an alternative","any":["review","probation","three months","in writing","contract","alternatively","learning budget","certification"]}],"model_answer":"Dear Nilufar,\nThank you very much for the offer. I'm genuinely excited about joining the backend team and I'd like to accept. Before I confirm, I was wondering whether there might be some flexibility on the starting salary. During my course I built two complete projects with the same technology your team uses, so I had hoped for something slightly closer to the upper end of the junior range. If the base salary can't change, would it be possible to state in the contract that my salary will be increased after a successful probation review?\nKind regards,\nSardor","min_words":80},"target_skill_key":"writing.task_completion","estimated_minutes":8,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":3,"service_key":"speaking","step_type":"speak","title":"Negotiate on the call","instructions":"Nilufar calls you. She says the base salary can only go up slightly. Respond: accept or discuss the small increase, ask for the review to be written in the contract, and confirm the next step.","prompt_text":"Nilufar: Thanks for your email, Sardor. I've spoken to the team lead. We can raise the base salary a little, but not to the level you mentioned. How do you feel about that?","expected_answer_json":{"goal":"Reach a fair agreement politely and confirm the next step.","points":[{"label":"respond positively to the increase","any":["thank*","appreciate","that's fair","sounds good","i understand","that works","happy with"]},{"label":"ask for the review in the contract","any":["review","probation","in writing","contract","written","three months"]},{"label":"confirm the next step","any":["send","updated","sign","confirm","next step","look forward","new offer","revised"]}],"model_answer":"Thank you, I really appreciate you checking with the team lead. I understand the base salary has limits. I'd be happy to accept the increase if we could also put in writing that my salary will be reviewed after the three-month probation. If that's possible, could you send me the updated offer, and I'll sign it this week?"},"target_skill_key":"speaking.task_completion","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
