    from jsonb_populate_record(null::public.immersion_missions, $seed${"slug":"b2-student-visa-interview","title":"A student visa interview","level":"B2","status":"published","sort_order":200,"metadata":{},"context_text":"You have been accepted onto a one-year master's programme abroad, and your student visa application requires an interview at the embassy. Your appointment is next Thursday. You want to be well prepared and answer the officer's questions clearly and honestly.","objective_text":"Check the documents you must bring, understand the officer's questions, prepare your study plan in writing and answer confidently in the interview.","mission_type":"study","target_vocabulary":["acceptance letter","proof of funds","bank statement","sponsor","accommodation","ties to home","intend to"],"target_grammar":"future forms and purpose clauses (I'm going to study…, I plan to return in order to…, so that I can…)","cultural_note":"Visa officers usually want three things: that you are a genuine student, that you can pay for your studies, and that you have a clear plan. Short, honest, specific answers work far better than long memorised speeches. Rules differ by country, so always check the official embassy website.","success_conditions_json":["Identify the documents needed and the common mistakes","Understand what the officer asks and why","Write a short, specific study plan","Answer interview questions clearly and honestly"],"skill_mix":["reading","listening","writing","speaking"]}$seed$::jsonb) r
