    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the appointment notice","instructions":"Read the notice that came with your appointment confirmation. Then answer the questions.","prompt_text":"YOUR VISA INTERVIEW\nPlease arrive 20 minutes before your appointment. Bring the ORIGINAL documents and one copy of each:\n- valid passport\n- letter of acceptance from your university\n- proof of funds for tuition and living costs (for example, bank statements for the last three months, or a letter from your sponsor with their bank statements)\n- proof of accommodation, if available\nApplicants who arrive late or without the original documents may have to book a new appointment. Phones must be switched off in the waiting area.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What must you bring for each document?","options":["Two copies","The original and one copy","A translated copy only"],"answer":1,"explanation":"\"Bring the ORIGINAL documents and one copy of each.\""},{"id":"q2","prompt":"If your parents pay for your studies, what do you need?","options":["A letter from them with their bank statements","Their passports","Nothing extra"],"answer":0,"explanation":"\"A letter from your sponsor with their bank statements.\""},{"id":"q3","prompt":"Which document is only needed if you have it?","options":["The acceptance letter","Proof of funds","Proof of accommodation"],"answer":2,"explanation":"\"Proof of accommodation, if available.\""}]},"target_skill_key":"reading.detail","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
