    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to a practice interview","instructions":"Your university's international office runs a practice interview. Listen to the adviser playing the officer. Then answer the questions.","prompt_text":"Officer: Good morning. Why did you choose this university rather than one in your own country?\nOfficer: And how is your course connected to what you studied before?\nOfficer: Who is paying for your tuition and your living costs?\nOfficer: What are your plans after you graduate?\nAdviser: OK, let's stop there. Remember, the officer isn't trying to trick you. Each question checks one thing: that your choice makes sense, that you can afford it, and that you have a realistic plan. Keep your answers short and specific, and never guess at a number you don't know. It's fine to say, 'Let me check the document.'","expected_answer_json":{"questions":[{"id":"q1","prompt":"According to the adviser, what is the officer checking?","options":["Your English accent","That your choice makes sense, you can afford it, and your plan is realistic","How many universities you applied to"],"answer":1,"explanation":"\"Each question checks one thing: that your choice makes sense, that you can afford it, and that you have a realistic plan.\""},{"id":"q2","prompt":"What should you do if you don't know an exact number?","options":["Give your best guess","Change the subject","Say you will check the document"],"answer":2,"explanation":"\"Never guess at a number you don't know. It's fine to say, 'Let me check the document.'\""}]},"target_skill_key":"listening.detail","estimated_minutes":4,"status":"published","metadata":{"accent":"us"}}$seed$::jsonb) r;
