    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"writing","step_type":"reply","title":"Write your study plan","instructions":"The application asks for a short study plan. Write about why you chose this course, how it connects to your past studies or work, how you will pay for it, and what you plan to do afterwards.","prompt_text":"Study plan (please write in English):","expected_answer_json":{"goal":"Write a clear, specific and honest study plan.","points":[{"label":"explain why this course","any":["chose","choose","because","programme","program","course","module*","specialis*","speciali*"]},{"label":"connect it to past studies or work","any":["bachelor","degree","previous*","worked","experience","studied","background"]},{"label":"say how you will pay","any":["scholarship","sponsor*","parents","savings","pay","fund*","tuition"]},{"label":"describe plans after graduation","any":["after","return","go back","plan to","intend to","career","home","graduat*"]}],"model_answer":"I have chosen the one-year master's in Data Analytics because its modules on public health data match the work I want to do. I studied mathematics for my bachelor's degree in Tashkent and then worked for two years as a junior analyst at a clinic network, where I saw how much better data could improve patient care. My tuition is covered by a university scholarship, and my parents will pay my living costs; their letter and bank statements are attached. After graduating, I plan to return to Uzbekistan and work in healthcare analytics.","min_words":80},"target_skill_key":"writing.task_completion","estimated_minutes":9,"status":"published","metadata":{}}$seed$::jsonb) r;
