    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the renewal notice","instructions":"Read the notice from your landlord. Then answer the questions.","prompt_text":"Dear Tenant,\nYour current lease ends on 31 May. I would be happy to renew it for a further twelve months. Due to rising maintenance and property costs, the new monthly rent would be increased by 25%, payable from 1 June.\nPlease confirm by 30 April whether you wish to renew on these terms. If I do not hear from you by then, I will assume you intend to leave at the end of the current lease and will begin advertising the flat.\nKind regards,\nMr Demir","expected_answer_json":{"questions":[{"id":"q1","prompt":"What reason does the landlord give for the increase?","options":["Rising maintenance and property costs","A new tenant has offered more","Repairs you caused"],"answer":0,"explanation":"\"Due to rising maintenance and property costs.\""},{"id":"q2","prompt":"What happens if you don't reply by 30 April?","options":["The lease renews automatically at the old rent","The landlord will assume you are leaving","The increase is cancelled"],"answer":1,"explanation":"\"I will assume you intend to leave at the end of the current lease and will begin advertising the flat.\""}]},"target_skill_key":"reading.detail","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
