    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to the landlord","instructions":"You meet Mr Demir on the stairs and he talks to you briefly. Listen. Then answer the questions.","prompt_text":"Ah, hello! You got my letter? I know, I know, it's a big jump. To be honest with you, it's not really about the money from you. The building needs a new roof next year, and the bank wants me to show steady income from the flats. The last thing I want is the flat empty for two months while I look for someone new. You've never been late once. If you could commit for a longer period, maybe we could talk about the number.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What does the landlord most want to avoid?","options":["Paying for a new roof","The flat being empty","Talking to the bank"],"answer":1,"explanation":"\"The last thing I want is the flat empty for two months while I look for someone new.\""},{"id":"q2","prompt":"What does he hint he would accept in exchange for a lower increase?","options":["A longer commitment from you","Payment in cash","You doing repairs yourself"],"answer":0,"explanation":"\"If you could commit for a longer period, maybe we could talk about the number.\""},{"id":"q3","prompt":"Why does he need steady income?","options":["He is selling the building","The bank wants to see it before the roof work","He is moving abroad"],"answer":1,"explanation":"\"The building needs a new roof next year, and the bank wants me to show steady income.\""}]},"target_skill_key":"listening.detail","estimated_minutes":4,"status":"published","metadata":{"accent":"gb"}}$seed$::jsonb) r;
