    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"writing","step_type":"reply","title":"Write your counter-offer","instructions":"Reply to Mr Demir in writing before the deadline. Acknowledge his situation, remind him of your record as a tenant, and make a specific counter-offer that uses what you learned on the stairs.","prompt_text":"To: Mr Demir\nSubject: Lease renewal – flat 7","expected_answer_json":{"goal":"Make a reasoned, specific counter-offer that meets both sides' interests.","points":[{"label":"acknowledge his situation","any":["understand","appreciate","costs","roof","while i","i realise","i realize"]},{"label":"mention your record as a tenant","any":["on time","never late","two years","reliable","looked after","good condition","careful"]},{"label":"make a specific counter-offer","any":["per cent","percent","increase of","prepared to","willing to","offer"]},{"label":"offer a longer commitment","any":["two-year","two years","24 months","longer","eighteen months","18 months","commit*","fixed term"]}],"model_answer":"Dear Mr Demir,\nThank you for your letter and for explaining the situation with the roof when we spoke. I'd very much like to stay in the flat. While I understand that your costs have risen, a 25% increase is more than I can manage. Over the past two years I have always paid on time and kept the flat in good condition, and I would be happy to offer you more stability: if you were willing to limit the increase to 10%, I would be prepared to sign a two-year fixed-term lease. That would guarantee your income for the bank and avoid any empty months.\nBest regards,\nAnvar Rashidov","min_words":100},"target_skill_key":"writing.task_completion","estimated_minutes":9,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":3,"service_key":"speaking","step_type":"speak","title":"Agree terms on the phone","instructions":"Mr Demir calls. He proposes a middle figure. Respond: weigh up his offer, propose or accept a final compromise, and confirm the terms clearly so there is no misunderstanding.","prompt_text":"Mr Demir: I read your email. Ten per cent is too low for me, but I like the idea of two years. What would you say to fifteen?","expected_answer_json":{"goal":"Reach a compromise and confirm the terms precisely.","points":[{"label":"respond to his offer","any":["fifteen","15","twelve","12","meet halfway","middle","that's fair","i could accept"]},{"label":"link it to the longer lease","any":["two years","two-year","24 months","fixed","lease","commit*"]},{"label":"confirm the terms clearly","any":["so just to confirm","to confirm","in writing","from 1 june","send me","new contract","agreed","sign"]}],"model_answer":"Thank you for considering it. Fifteen is still quite a stretch for me, but I'd like to find a middle ground. Could we meet at twelve per cent for a two-year fixed lease? If that works for you, then just to confirm: twelve per cent from the first of June, fixed for twenty-four months. Could you send me the new contract in writing so I can sign it this week?"},"target_skill_key":"speaking.task_completion","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
