  -- immersion: c2-breaking-bad-news-to-a-client (C2)
  if exists (select 1 from public.immersion_missions where product_id = v_product_immersion and language_id = v_en_id and slug = 'c2-breaking-bad-news-to-a-client') then
    raise notice 'skipped existing immersion item %', 'c2-breaking-bad-news-to-a-client';
  else
    insert into public.immersion_missions (slug, title, level, status, sort_order, metadata, context_text, objective_text, mission_type, target_vocabulary, target_grammar, cultural_note, success_conditions_json, skill_mix, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.context_text, r.objective_text, r.mission_type, r.target_vocabulary, r.target_grammar, r.cultural_note, r.success_conditions_json, r.skill_mix, v_product_immersion, v_en_id
    from jsonb_populate_record(null::public.immersion_missions, $seed${"slug":"c2-breaking-bad-news-to-a-client","title":"Breaking bad news to a client","level":"C2","status":"published","sort_order":200,"metadata":{},"context_text":"You are the account director at a small digital agency in Tashkent. For six months your team has been building a customer loyalty app for a regional chain of bakeries. Yesterday an independent security review found serious flaws in how the app stores customer data. The launch, scheduled for next week and already announced to the client's customers, cannot go ahead.","objective_text":"Understand exactly what went wrong and who is responsible, anticipate the client's reaction, put the news in writing with genuine accountability, and handle the first difficult conversation.","mission_type":"workplace","target_vocabulary":["security review","vulnerability","remediation","accountability","revised timeline","at our expense","mitigate"],"target_grammar":"accountability without over-apology (We should have…, That was our responsibility, What we're doing now is…, I won't pretend that…)","cultural_note":"When delivering bad news to a client, credibility comes from owning the failure precisely, neither minimising it nor dramatising it, and from arriving with a concrete plan. Blaming a junior colleague or a third party, even when partly justified, almost always damages the relationship further.","success_conditions_json":["Pinpoint the cause of the failure and the agency's responsibility","Anticipate the client's priorities and likely reaction","Write a candid message that owns the problem and offers a plan","Stay composed and constructive when the client reacts angrily"],"skill_mix":["reading","listening","writing","speaking"]}$seed$::jsonb) r
    returning id into v_parent_id;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the review summary","instructions":"Read the summary from the independent security reviewer. Then answer the questions.","prompt_text":"Summary of findings\nThe application stores customers' phone numbers and purchase histories in a way that could, under certain conditions, be accessed by other users. No evidence was found that any real customer data has been exposed, as the app has only been used with test accounts. The flaw stems from a shortcut taken in the account system during an earlier sprint, which was not revisited before final testing. We do not recommend launching until this is fixed and re-tested. Estimated remediation: three weeks, plus one week of re-testing.","expected_answer_json":{"questions":[{"id":"q1","prompt":"Has any real customer data been exposed?","options":["Yes, phone numbers were leaked","No evidence of that, as only test accounts were used","It is impossible to say"],"answer":1,"explanation":"\"No evidence was found that any real customer data has been exposed, as the app has only been used with test accounts.\""},{"id":"q2","prompt":"What does the report suggest about responsibility?","options":["The client's requirements were unclear","A shortcut by the development team was never revisited","The reviewer missed it earlier"],"answer":1,"explanation":"\"The flaw stems from a shortcut taken... which was not revisited before final testing.\""},{"id":"q3","prompt":"How long is the delay likely to be?","options":["About one week","About four weeks","About three months"],"answer":1,"explanation":"Three weeks of remediation plus one week of re-testing."}]},"target_skill_key":"reading.detail","estimated_minutes":5,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to your colleague's warning","instructions":"Your project manager, who knows the client well, leaves you a voice message. Listen. Then answer the questions.","prompt_text":"Hi, it's Kamila. Just before you speak to Rustam: he's going to be furious, and some of it will be about face, not just the app. He told his whole board the launch date himself, and there are posters in every shop. So whatever you do, don't lead with the technical detail; he'll hear it as excuses. He respects people who are straight with him. And be careful with promises. If we give him a new date and miss that one too, we've lost the account. I'd rather we under-promise and he's pleasantly surprised.","expected_answer_json":{"questions":[{"id":"q1","prompt":"Why, according to Kamila, will Rustam be especially upset?","options":["He has already lost money","He announced the date publicly and personally","He dislikes the agency"],"answer":1,"explanation":"\"He told his whole board the launch date himself, and there are posters in every shop.\""},{"id":"q2","prompt":"What does she advise you NOT to do?","options":["Be honest about the delay","Begin with the technical explanation","Offer a new date at all"],"answer":1,"explanation":"\"Don't lead with the technical detail; he'll hear it as excuses.\""},{"id":"q3","prompt":"What is her view on the new launch date?","options":["Give the earliest possible date","Choose a cautious date you are sure you can meet","Let the client choose"],"answer":1,"explanation":"\"I'd rather we under-promise and he's pleasantly surprised.\""}]},"target_skill_key":"listening.detail","estimated_minutes":4,"status":"published","metadata":{"accent":"us"}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"writing","step_type":"reply","title":"Write to the client","instructions":"Write to Rustam before your call. Lead with the decision, take clear responsibility, reassure him about customer data without minimising the issue, and set out a realistic plan, including what the agency will do at its own cost.","prompt_text":"To: Rustam (Managing Director)\nSubject: Loyalty app launch: an important update","expected_answer_json":{"goal":"Deliver the news candidly, own the failure and present a credible plan.","points":[{"label":"lead with the decision","any":["cannot launch","can't launch","will not launch","won't launch","postpone*","delay*","not go ahead"]},{"label":"take clear responsibility","any":["our responsibility","our fault","we should have","our mistake","we take full","accountab*","we failed","our error"]},{"label":"reassure about customer data","any":["no customer data","no real customer","test accounts","not exposed","no evidence","safe"]},{"label":"set out the plan and cost","any":["at our expense","at our own cost","no extra cost","free of charge","plan","re-test*","weeks","new date","revised"]}],"model_answer":"Dear Rustam,\nI'm writing with difficult news, and I'd rather you heard it plainly: we cannot launch the loyalty app next week.\nAn independent security review found a serious flaw in how the app stores customer information. No real customer data has been exposed, because the app has only been used with test accounts, but launching in its current state would put your customers at risk. The flaw comes from a shortcut our team took months ago and should have caught before final testing. That was our responsibility, not yours.\nWe will fix and fully re-test the app at our own expense. Our realistic estimate is four to five weeks, and I would rather give you a date we will certainly meet than one we might miss. We will also cover the cost of updating the launch materials in your shops.\nI'd value the chance to talk this through with you today.\nWith apologies and respect,\nMadina","min_words":140},"target_skill_key":"writing.task_completion","estimated_minutes":10,"status":"published","metadata":{}}$seed$::jsonb) r;
