    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":3,"service_key":"speaking","step_type":"speak","title":"Handle the client's anger","instructions":"Rustam calls you, clearly angry. Respond: let him finish, acknowledge the damage to him personally, restate your responsibility without grovelling, and move the conversation towards one concrete next step.","prompt_text":"Rustam: I've just read your email. I stood in front of my board and gave them that date. Do you have any idea how this makes me look? Six months, and you tell me a week before launch?","expected_answer_json":{"goal":"De-escalate with empathy and accountability, then agree a next step.","points":[{"label":"acknowledge the personal impact","any":["board","position","i understand","you're right","put you","embarrass*","how it looks"]},{"label":"restate responsibility","any":["our fault","our responsibility","we should have","on us","our mistake","i take","we let you down"]},{"label":"propose a concrete next step","any":["meet","tomorrow","come to","board","explain","plan","timeline","this afternoon","in person"]}],"model_answer":"You're right, and I won't pretend otherwise. You put your name to that date in front of your board, and we've put you in a very difficult position. We should have caught this flaw months ago, and that's on us. What I'd like to do is come to your office tomorrow with our technical lead and a detailed plan, and if it would help, I'll explain the situation to your board myself, so that the responsibility sits where it belongs."},"target_skill_key":"speaking.task_completion","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
