    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.context_text, r.objective_text, r.mission_type, r.target_vocabulary, r.target_grammar, r.cultural_note, r.success_conditions_json, r.skill_mix, v_product_immersion, v_en_id
    from jsonb_populate_record(null::public.immersion_missions, $seed${"slug":"c2-moderating-a-panel-discussion","title":"Moderating a panel discussion","level":"C2","status":"published","sort_order":200,"metadata":{},"context_text":"You are moderating a sixty-minute panel at a regional education technology conference, titled \"Will AI tutors widen or narrow the learning gap?\". The panel has three speakers: a school headteacher, a start-up founder and a university researcher. At rehearsal, one panellist spoke for twice his allotted time, and the organisers have asked you to keep things balanced and on schedule.","objective_text":"Absorb the brief and the panellists' positions, understand the organisers' concerns, draft your opening framing, and steer the live discussion when one speaker dominates.","mission_type":"workplace","target_vocabulary":["moderator","run of show","allotted time","dominate","bring in","press on","wrap up"],"target_grammar":"diplomatic interruption and redirection (If I could just bring in…, I'm conscious of time, so…, Let me press you on that…, Before we move on…)","cultural_note":"A good moderator protects the audience's time, not the speakers' egos. Interrupting is expected and accepted when it is done briefly, with a reason and a handover; what audiences resent is a moderator who lets one voice take over.","success_conditions_json":["Understand the format, timings and each speaker's stance","Grasp the organisers' concerns and the agreed signals","Write an opening that frames the question and sets the rules","Interrupt a dominating speaker gracefully and redistribute the floor"],"skill_mix":["reading","listening","writing","speaking"]}$seed$::jsonb) r
    returning id into v_parent_id;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the run of show","instructions":"Read the organisers' brief. Then answer the questions.","prompt_text":"RUN OF SHOW – Panel 3, Main Hall\n00:00 Moderator opening (max. 3 min): frame the question, introduce speakers by name and role only; full bios are in the app.\n00:03 Opening statements: 3 min each, strict. Order: researcher, headteacher, founder.\n00:12 Moderated discussion (30 min).\n00:42 Audience Q&A via the app (15 min). Prioritise questions from teachers.\n00:57 One-sentence closing from each speaker.\nNotes: Dr Haydarova cautions that most evidence so far comes from well-resourced schools. Mr Laine (founder) will argue AI tutors can reach students without access to private tutoring. Ms Okafor (headteacher) is broadly supportive but worried about teacher workload. Mr Laine overran by four minutes at rehearsal.","expected_answer_json":{"questions":[{"id":"q1","prompt":"How should the moderator introduce the speakers?","options":["With their full biographies","By name and role only","By letting them introduce themselves"],"answer":1,"explanation":"\"Introduce speakers by name and role only; full bios are in the app.\""},{"id":"q2","prompt":"Which panellist's caution concerns the evidence base?","options":["Dr Haydarova","Ms Okafor","Mr Laine"],"answer":0,"explanation":"\"Dr Haydarova cautions that most evidence so far comes from well-resourced schools.\""},{"id":"q3","prompt":"What can be inferred from the final note?","options":["Mr Laine may need to be kept to time","Mr Laine will not attend","The panel will finish early"],"answer":0,"explanation":"He \"overran by four minutes at rehearsal\", so the moderator should expect to manage his time."}]},"target_skill_key":"reading.detail","estimated_minutes":5,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to the organiser's briefing","instructions":"Ten minutes before the session, the organiser speaks to you backstage. Listen. Then answer the questions.","prompt_text":"Right, two things. First, the feedback from yesterday's sessions was blunt: people felt the panels turned into sales pitches. So if anyone, and I think we both know who I mean, starts listing product features, please don't let it run. Second, the timekeeper in the front row will hold up a yellow card at one minute left and a red card at time. Speakers have been told, so you've got cover; you won't look rude cutting someone off at red. Oh, and the researcher is quite softly spoken, so make a point of bringing her in, otherwise she'll just wait politely and never get the floor.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What was the main complaint about yesterday's panels?","options":["They started late","They felt like sales pitches","The moderators were too strict"],"answer":1,"explanation":"\"People felt the panels turned into sales pitches.\""},{"id":"q2","prompt":"What does the red card mean?","options":["One minute left","The speaker's time is up","Audience questions can begin"],"answer":1,"explanation":"\"A yellow card at one minute left and a red card at time.\""},{"id":"q3","prompt":"Why does the organiser mention the researcher?","options":["She tends to overrun","She is unlikely to claim the floor herself","She has cancelled"],"answer":1,"explanation":"\"She'll just wait politely and never get the floor\", so the moderator must bring her in."}]},"target_skill_key":"listening.detail","estimated_minutes":4,"status":"published","metadata":{"accent":"gb"}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"writing","step_type":"reply","title":"Write your opening","instructions":"Draft the words you will say in your three-minute opening. Frame the question so that it feels genuinely open, introduce the three speakers briefly, explain the format and the timing signals, and invite the audience to submit questions.","prompt_text":"Moderator's opening – script draft","expected_answer_json":{"goal":"Write a crisp, balanced opening that frames the debate and sets expectations.","points":[{"label":"frame the question as genuinely open","any":["widen","narrow","gap","question","both","promise","risk*","evidence"]},{"label":"introduce the speakers briefly","any":["haydarova","okafor","laine","researcher","headteacher","founder","joined by"]},{"label":"explain the format and timing","any":["three minutes","3 minutes","opening statement*","card*","timekeeper","strict","discussion"]},{"label":"invite audience questions","any":["app","question*","q&a","submit","send in","audience"]}],"model_answer":"Good afternoon, and welcome. The promise of AI tutors is easy to state: personalised help for every learner, at almost no cost. Whether that promise narrows the learning gap, or quietly widens it, is a much harder question, and it's the one we're here to test. I'm joined by Dr Haydarova, an education researcher; Ms Okafor, a secondary headteacher; and Mr Laine, the founder of an AI tutoring start-up. Each will make a three-minute opening statement, and our timekeeper in the front row will help us all stay honest: yellow means one minute, red means time. After that we'll open the discussion, and in the final fifteen minutes I'll put your questions to the panel, so please send them in through the app now, especially if you teach.","min_words":120},"target_skill_key":"writing.task_completion","estimated_minutes":10,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
